/**
 * Preview only.
 *
 * The authority for any quote a user acts on is `quoteBuy` / `quoteSell` read from the curve
 * contract at a block. This port exists so an interface can show a number before a round trip,
 * and it is held to the Solidity result by `test/curve-math.test.ts`, which replays vectors
 * generated by `contracts/test/CurveVectors.t.sol`. If the two ever disagree, the chain is
 * right and this file is wrong.
 *
 * Every amount is in atomic units. Rounding mirrors `PicklerCurveMath`: the quote reserve is
 * floored and anything subtracted from a reserve is ceilinged, so errors favour the curve.
 */
export interface CurveConfig {
  virtualTokenReserve: bigint;
  virtualQuoteReserve: bigint;
  saleAllocation: bigint;
}

/**
 * Tokens delivered for a net quote amount, after fees have already been deducted.
 *
 * The result is not capped to the remaining inventory — near the end of the curve it can
 * exceed it. Compare against {@link remainingTokens} before showing it; on chain that case
 * reverts and the buyer is offered an exact-output purchase instead.
 */
export function tokensOutForQuoteIn(
  config: CurveConfig,
  netSold: bigint,
  quoteNetIn: bigint,
): bigint {
  if (quoteNetIn === 0n) {
    return 0n;
  }

  const k = config.virtualTokenReserve * config.virtualQuoteReserve;
  const x = config.virtualTokenReserve - netSold;
  const q = k / x;

  const newX = ceilDiv(k, q + quoteNetIn);

  return newX >= x ? 0n : x - newX;
}

/** Tokens still available on the curve. */
export function remainingTokens(config: CurveConfig, netSold: bigint): bigint {
  return config.saleAllocation - netSold;
}

function ceilDiv(numerator: bigint, denominator: bigint): bigint {
  return numerator === 0n ? 0n : (numerator - 1n) / denominator + 1n;
}
